import {courses,byId,groups,streams,patterns,initial,term,issues,allIssues,coverage,generate,degreeTermCount,visibleTerms} from './model.mjs';
const $=s=>document.querySelector(s),storageKey='uwflow-prototype-v1';
let state=initial(),tab='roadmap',filter='All',wishQuery='',lines=true,dragId=null,undo=null;
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved?.version===1&&streams[saved.state.program]?.includes(saved.state.stream)&&Array.isArray(saved.state.completed)&&saved.state.positions)state={...initial(),...saved.state};}catch{}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,3500)}
function save(announce=false){try{localStorage.setItem(storageKey,JSON.stringify({version:1,state}));if(announce)toast('Plan saved in this browser.')}catch{toast('Browser storage unavailable. Keep this tab open to retain edits.')}}
function modal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){$('#modal').close()}$('#modal .close').onclick=close;
const total=Object.entries(groups).filter(([g])=>g!=='pd').reduce((a,[,g])=>a+g.target,0);
function summary(){const done=Object.keys(groups).filter(g=>g!=='pd').reduce((n,g)=>n+coverage(state,g),0),planned=Object.keys(groups).filter(g=>g!=='pd').reduce((n,g)=>n+coverage(state,g,true),0),errors=allIssues(state);return `<div class="stats"><div class="panel"><div class="row between"><h3>Progress</h3><span>${Math.round(done/total*100)}% complete</span></div><div class="bar large"><span style="width:${done/total*100}%"></span></div></div><div class="panel row"><span class="round">◇</span><div><h3>Credits completed</h3><div class="metric">${(done*.5).toFixed(1)} / ${(total*.5).toFixed(1)}</div></div></div><div class="panel row"><span class="round ${errors.length?'':'green'}">${errors.length?'!':'✓'}</span><div><h3>${errors.length?errors.length+' scheduling issues':planned===total?'Requirements covered':'Requirements remaining'}</h3><span class="small muted">${total-planned} requirement slots remain after valid planned courses.</span></div></div></div>`}
function details(){const c=byId[state.selected],errs=c?issues(state,c.id):[];return `<details class="panel sidebar-section" data-section="course" ${state.collapsed?.course?'':'open'}><summary>Course details</summary><div class="section-content">${c?`<div class="details-title">${c.code} — ${c.name}</div><div class="detail-row"><b>Prerequisites</b><span>${c.prereqs.map(id=>`${state.completed.includes(id)?'✓ ':''}${byId[id].code}`).join(', ')||'None'}</span></div><div class="detail-row"><b>Antirequisites</b><span>${c.anti.map(id=>byId[id].code).join(', ')||'None'}</span></div><div class="detail-row"><b>Offered in</b><span>${c.offered.join(', ')}</span></div><div class="detail-row"><b>Requirement</b><span>${groups[c.group].name}</span></div>${errs.map(m=>`<div class="notice warning">⚠ ${m}</div>`).join('')}<div class="row"><a href="https://uwflow.com/course/${c.id.toLowerCase()}" target="_blank" rel="noopener">Ratings & reviews ↗</a><button class="mini" data-wish="${c.id}">${state.wishlist.includes(c.id)?'Remove wish':'＋ Wishlist'}</button></div><hr><label class="small">Move selected course<select id="move-target" style="width:100%;margin:6px 0"><option value="">Unscheduled</option>${Array.from({length:state.termCount},(_,i)=>`<option value="${i}" ${state.positions[c.id]===i?'selected':''}>${term(state,i).title} · ${term(state,i).type}</option>`).join('')}</select></label><button id="move-selected" ${state.completed.includes(c.id)?'disabled':''}>Move course</button>`:'<p class="muted small">Select a course to view its details.</p>'}</div></details><details class="panel sidebar-section" data-section="requirements" ${state.collapsed?.requirements?'':'open'}><summary>Requirement details</summary><div class="section-content"><b>${state.program==='SE'?'Software':'Computer'} Engineering (${state.stream})</b><div class="small muted">${total*.5} credits · illustrative requirement set</div>${Object.entries(groups).map(([g,v])=>`<div class="requirement"><div class="row between small"><span>${v.name}</span><span>${coverage(state,g)} / ${v.target}</span></div><div class="bar"><span style="width:${coverage(state,g)/v.target*100}%"></span></div></div>`).join('')}</div></details><details class="panel sidebar-section" data-section="legend" ${state.collapsed?.legend?'':'open'}><summary>Legend</summary><div class="section-content"><div class="legend-item"><span class="legend-icon filled">✓</span><div><b>Completed</b><br>Course taken and credited</div></div><div class="legend-item"><span class="legend-icon"></span><div><b>Planned</b><br>Scheduled for a future term</div></div><div class="legend-item"><span class="legend-icon dashed">＋</span><div><b>Requirement slot</b><br>Choose an eligible course</div></div><div class="small muted">Solid arrows: prerequisite order satisfied.<br>Dashed amber arrows: timing conflict.</div></div></details>`}
function courseCard(c){const completed=state.completed.includes(c.id),err=issues(state,c.id);return `<button class="course ${completed?'completed':''} ${err.length?'problem':''} ${state.selected===c.id?'selected':''}" data-course="${c.id}" draggable="${!completed}" aria-pressed="${state.selected===c.id}"><b>${completed?'✓ ':''}${c.code}</b><small>${c.name}</small>${err.length?'<span class="tag amber">⚠ '+(err.some(e=>e.includes('earlier'))?'Missing prereq':'Schedule issue')+'</span>':''}</button>`}
function board(){const available=visibleTerms(state,tab),size=tab==='roadmap'?5:6;state.viewStart=Math.max(0,Math.min(state.viewStart,Math.max(0,available.length-size)));const indices=state.fullDegree?available:available.slice(state.viewStart,state.viewStart+size);return `<div class="panel"><div class="row between toolbar"><button id="toggle-sidebar" aria-expanded="${!state.hideSidebar}">${state.hideSidebar?'Show details panel':'Hide details panel'}</button><div class="row"><label class="small"><input id="full-degree" type="checkbox" ${state.fullDegree?'checked':''}> All terms · horizontal scroll</label>${tab==='planner'?`<label class="small"><input id="show-work" type="checkbox" ${state.showWork!==false?'checked':''}> Show work terms</label>`:''}</div><div class="small muted">${term(state,0).title} → ${term(state,state.termCount-1).title} · expected end</div></div><div class="row between toolbar"><div class="row"><button id="previous" ${state.fullDegree?'hidden':''} aria-label="Previous terms" ${state.viewStart===0?'disabled':''}>←</button><span class="small muted">${tab==='roadmap'?'Study terms':'Four-month terms'} · ${indices.length?term(state,indices[0]).title:''}–${indices.length?term(state,indices.at(-1)).title:''}</span><button id="next" ${state.fullDegree?'hidden':''} ${state.viewStart+size>=available.length?'disabled':''} aria-label="Next terms">→</button></div><label class="small"><input type="checkbox" id="lines" ${lines?'checked':''}> Prerequisite lines</label></div><div class="board-scroll"><div class="board ${state.fullDegree?'full-degree':''}" style="${state.fullDegree?'width:'+Math.max(1,indices.length)*190+'px':''}"><svg class="connections" aria-label="Course prerequisite connections" role="img"></svg><div class="columns" style="--cols:${indices.length}">${indices.map((i,k)=>{const t=term(state,i),items=courses.filter(c=>state.positions[c.id]===i).sort((a,b)=>(state.order?.indexOf(a.id)??courses.indexOf(a))-(state.order?.indexOf(b.id)??courses.indexOf(b)));return `<section class="term ${t.type!=='Study'?'work':''}" data-term="${i}"><div class="term-head"><strong>${t.type==='Study'?t.level:t.type}</strong><span>${t.title}</span>${tab==='planner'?`<select class="term-options" data-type="${i}" aria-label="Type of ${t.title}">${['Study','Work','Exchange','Break'].map(v=>`<option ${t.type===v?'selected':''}>${v}</option>`).join('')}</select>`:''}</div><div class="term-body">${items.map(courseCard).join('')}${t.type==='Study'?`<button class="course ghost" data-group="${['science','listc','technical','free'][k%4]}" data-destination="${i}">＋ ${groups[['science','listc','technical','free'][k%4]].name}</button>`:t.type==='Work'?`<button class="course ghost" data-group="pd" data-destination="${i}">＋ Add PD</button>`:''}<button class="course ghost" data-add-course="${i}">＋ Add course</button></div></section>`}).join('')}</div></div></div></div>`}
function planner(){return `${summary()}<div class="row between toolbar"><div class="row"><button id="generate" class="primary">✧ Generate plan</button><button id="add-term">＋ Add term</button><label class="small">Course limit <select id="limit">${[2,3,4,5,6].map(n=>`<option ${n===state.limit?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="row"><button id="history">Completed courses</button><button id="save" class="outline">Save plan</button></div></div><div class="workspace ${state.hideSidebar?'sidebar-hidden':''}"><div>${board()}<div class="panel" style="margin-top:20px"><h3>Unscheduled wishlist courses</h3><p class="small muted">Drag a course into a study term. Select any course for keyboard-accessible move controls.</p><div class="bank" data-term="">${state.wishlist.filter(id=>state.positions[id]==null&&!state.completed.includes(id)).map(id=>courseCard(byId[id])).join('')||'<span class="small muted">All wishlist courses are scheduled.</span>'}</div><h3>Plan validation</h3><div class="small">${allIssues(state).map(e=>`<div class="notice warning"><b>${byId[e.id].code}</b>: ${e.message}</div>`).join('')||'<div class="notice">No scheduling conflicts in the sample rules.</div>'}</div></div></div><aside class="sidebar" ${state.hideSidebar?'hidden':''}>${details()}</aside></div>`}
function wishlist(){const missing=id=>byId[id].prereqs.some(p=>!state.completed.includes(p)),nextSeason=term(state,1).season;const list=state.wishlist.filter(id=>(byId[id].code+' '+byId[id].name).toLowerCase().includes(wishQuery.toLowerCase())).filter(id=>filter==='All'||filter==='Fits requirements'&&coverage(state,byId[id].group,true)<groups[byId[id].group].target||filter==='Missing prereq'&&missing(id)||filter==='Offered next term'&&byId[id].offered.includes(nextSeason));const fits=state.wishlist.filter(id=>coverage(state,byId[id].group,true)<groups[byId[id].group].target).length;return `<div class="wishlist-layout"><section class="panel"><div class="row between"><h2>My wishlist</h2><button id="browse" class="outline">＋ Add courses</button></div><p class="muted">Courses you want to take and plan around.</p><label class="wishlist-search">Search wishlist<input id="wishlist-search" type="search" placeholder="Course code or name" value="${escape(wishQuery)}"></label><div class="filters">${['All','Fits requirements','Missing prereq','Offered next term'].map(f=>`<button data-filter="${f}" class="${f===filter?'active':''}">${f}</button>`).join('')}</div>${list.map(id=>{const c=byId[id],n=state.wishlist.indexOf(id);return `<article class="wish-row" draggable="true" data-priority="${id}"><span class="grip" aria-hidden="true">⠿</span><span class="rank">${n+1}</span><div><h3>${c.code}</h3><span>${c.name}</span></div><div><div class="wish-badges"><span class="tag ${missing(id)?'amber':'green'}">${missing(id)?'⚠ Missing prereq':'Fulfills requirement'}</span><span class="tag">${c.offered.join(' / ')}</span></div><span class="small muted">${missing(id)?'Needs '+c.prereqs.filter(p=>!state.completed.includes(p)).map(p=>byId[p].code).join(', '):groups[c.group].name}</span></div><div><button class="outline mini" data-plan="${id}">${state.positions[id]!=null?'View in plan':'Add to plan'}</button><div class="wish-actions" style="margin-top:7px"><button class="mini" data-up="${id}" aria-label="Raise ${c.code} priority" ${n===0?'disabled':''}>↑</button><button class="mini" data-down="${id}" aria-label="Lower ${c.code} priority" ${n===state.wishlist.length-1?'disabled':''}>↓</button><button class="mini" data-wish="${id}" aria-label="Remove ${c.code} from wishlist">×</button></div></div></article>`}).join('')||'<div class="empty">No courses match this filter.</div>'}</section><aside class="sidebar"><div class="panel"><h2>Wishlist summary</h2><div class="summary-grid"><div><b>${state.wishlist.length}</b><span class="small">saved</span></div><div><b>${fits}</b><span class="small">fit outstanding requirements</span></div><div><b>${state.wishlist.filter(id=>byId[id].offered.includes(nextSeason)&&!missing(id)).length}</b><span class="small">ready next term</span></div></div></div><div class="panel"><h2>Planning insights</h2><div class="insight">✓ ${fits} wishlist courses fit outstanding requirements.</div>${state.wishlist.filter(missing).slice(0,3).map(id=>`<div class="insight small">⚠ <b>${byId[id].code}</b> needs ${byId[id].prereqs.filter(p=>!state.completed.includes(p)).map(p=>byId[p].code).join(', ')} first.</div>`).join('')}<button class="primary" id="generate">Generate plan</button></div><div class="panel"><h2>Priority legend</h2><p class="insight">Priority 1 = highest preference.</p><p class="insight">Drag to reorder, or use the arrow buttons.</p><p class="insight small muted">Generation schedules required courses first, then wishlist courses in priority order. Existing placements are retained.</p></div></aside></div>`}
function render(){const start=performance.now();$('#content').dataset.view=tab;$('#program-summary').textContent=`${state.program==='SE'?'Software':'Computer'} Engineering • ${state.stream} Stream • ${state.calendar} Calendar ⌄`;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false')});$('#content').innerHTML=tab==='wishlist'?wishlist():tab==='planner'?planner():`${summary()}<div class="row between toolbar"><span class="small muted">Study-term roadmap · select a course to follow its prerequisites</span><div class="row"><button id="history">＋ Completed courses</button><button id="open-planner" class="outline">Edit term plan</button></div></div><div class="workspace ${state.hideSidebar?'sidebar-hidden':''}">${board()}<aside class="sidebar" ${state.hideSidebar?'hidden':''}>${details()}</aside></div>`;bind();requestAnimationFrame(draw);console.debug('Prototype render',Math.round(performance.now()-start)+'ms')}
function changeTab(value){tab=value;state.viewStart=0;render()}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>changeTab(b.dataset.tab));
function move(id,target){if(state.completed.includes(id)){toast('Edit completed history before moving this course.');return;}undo=structuredClone(state);if(target==='')delete state.positions[id];else state.positions[id]=Number(target);state.selected=id;save();render();const errors=allIssues(state);if(errors.length){modal(`<h2>Scheduling warning</h2><p class="muted">The move is shown in your draft. Review the conflicts below.</p>${errors.map(e=>`<div class="notice warning"><b>${byId[e.id].code}</b>: ${e.message}</div>`).join('')}<div class="dialog-actions"><button id="undo-move">Undo move</button><button class="primary" id="keep-move">Keep and review</button></div>`);$('#undo-move').onclick=()=>{state=undo;save();close();render()};$('#keep-move').onclick=close;}}
function roundedRoute(points){const pts=points.filter((p,i)=>!i||p[0]!==points[i-1][0]||p[1]!==points[i-1][1]);let d=`M${pts[0].join(' ')}`;for(let i=1;i<pts.length-1;i++){const a=pts[i-1],b=pts[i],c=pts[i+1],l1=Math.hypot(b[0]-a[0],b[1]-a[1]),l2=Math.hypot(c[0]-b[0],c[1]-b[1]),radius=Math.min(12,l1/2,l2/2);const entry=[b[0]+(a[0]-b[0])*radius/l1,b[1]+(a[1]-b[1])*radius/l1],exit=[b[0]+(c[0]-b[0])*radius/l2,b[1]+(c[1]-b[1])*radius/l2];d+=` L${entry.join(' ')} Q${b.join(' ')} ${exit.join(' ')}`;}return d+` L${pts.at(-1).join(' ')}`;}
function draw(){const svg=$('.connections'),board=$('.board');if(!svg||!board)return;svg.replaceChildren();if(!lines)return;const rect=board.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${board.offsetWidth} ${board.offsetHeight}`);const cards=[...board.querySelectorAll('[data-course]')];let edgeIndex=0;courses.forEach(c=>c.prereqs.forEach(p=>{const a=cards.find(n=>n.dataset.course===p),b=cards.find(n=>n.dataset.course===c.id);if(!a||!b)return;const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();const x=ar.right-rect.left,y=ar.top-rect.top+ar.height/2,u=br.left-rect.left,v=br.top-rect.top+br.height/2;const bad=state.completed.includes(p)?(state.completedTerms?.[p]!=null&&state.completedTerms[p]>=state.positions[c.id]):state.positions[p]>=state.positions[c.id],path=document.createElementNS('http://www.w3.org/2000/svg','path');const obstacles=[...board.querySelectorAll('.course')].map(el=>{const r=el.getBoundingClientRect();return {left:r.left-rect.left,right:r.right-rect.left,top:r.top-rect.top,bottom:r.bottom-rect.top}});const left=Math.min(x,u),right=Math.max(x,u);const clear=lane=>!obstacles.some(r=>r.left<right&&r.right>left&&lane>r.top-6&&lane<r.bottom+6);const candidates=[y,v,...obstacles.map(r=>r.bottom+14)];const lane=candidates.filter(clear).sort((a,b)=>(Math.abs(a-y)+Math.abs(a-v))-(Math.abs(b-y)+Math.abs(b-v)))[0]??(board.offsetHeight-15-(edgeIndex++%5)*4);const sx=x+7,tx=u-7;path.setAttribute('d',roundedRoute([[x,y],[sx,y],[sx,lane],[tx,lane],[tx,v],[u,v]])+` M${u-5} ${v-4} Q${u-2} ${v-1} ${u} ${v} Q${u-2} ${v+1} ${u-5} ${v+4}`);path.setAttribute('stroke-linejoin','round');path.setAttribute('fill','none');path.setAttribute('stroke',bad?'#b9821e':(state.selected===c.id||state.selected===p?'#0057ff':'#8290aa'));path.setAttribute('stroke-width','1.8');if(bad)path.setAttribute('stroke-dasharray','5 3');svg.append(path)}))}
new ResizeObserver(()=>requestAnimationFrame(draw)).observe($('#content'));
function settings(){modal(`<h2>Program & academic calendar</h2><div class="settings-grid"><label>Program<select id="program"><option value="SE" ${state.program==='SE'?'selected':''}>Software Engineering</option><option value="CE" ${state.program==='CE'?'selected':''}>Computer Engineering</option></select></label><label>Stream<select id="stream">${streams[state.program].map(s=>`<option ${s===state.stream?'selected':''}>${s}</option>`).join('')}</select></label><label>Start term<select id="start-season">${['Winter','Spring','Fall'].map(v=>`<option ${(state.startSeason||'Fall')===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Start year<input id="start-year" type="number" min="2020" max="2035" value="${state.startYear}"></label><label>Expected end term<select id="end-season">${['Winter','Spring','Fall'].map(v=>`<option ${term(state,state.termCount-1).season===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Expected end year<input id="end-year" type="number" min="2020" max="2045" value="${term(state,state.termCount-1).year}"></label><label>Academic calendar<select id="calendar">${['2024–2025','2025–2026','2026–2027','2027–2028'].map(c=>`<option ${c===state.calendar?'selected':''}>${c}</option>`).join('')}</select></label></div><p class="small muted">Engineering degrees span approximately five years in this demo. Set the first and expected final four-month term. Calendar is suggested from start year and can be overridden. Program and stream changes retain course placements for review. Sample courses are shared across programs for this UI demo.</p><div class="dialog-actions"><button id="apply-settings" class="primary">Apply settings</button></div>`);$('#program').onchange=e=>$('#stream').innerHTML=streams[e.target.value].map(s=>`<option>${s}</option>`).join('');$('#start-year').onchange=e=>{const y=Number(e.target.value);const c=`${y}–${y+1}`;if(![...$('#calendar').options].some(o=>o.value===c))$('#calendar').add(new Option(c,c));$('#calendar').value=c};$('#apply-settings').onclick=()=>{const y=Number($('#start-year').value);if(y<2020||y>2035||!Number.isInteger(y)){toast('Enter a start year between 2020 and 2035.');return;}const endYear=Number($('#end-year').value),count=degreeTermCount(y,$('#start-season').value,endYear,$('#end-season').value);if(!Number.isInteger(count)||count<1||count>30){toast('Choose an end date after the start, within 10 years.');return;}if(Object.values(state.positions).some(t=>t>=count)){toast('Move courses out of terms beyond the new end date first.');return;}state.startSeason=$('#start-season').value;state.termCount=count;state.program=$('#program').value;state.stream=$('#stream').value;state.startYear=y;state.calendar=$('#calendar').value;state.viewStart=0;save();close();render();toast('Program updated. Review scheduling issues in Planner.')}}
$('#settings').onclick=$('#program-summary').onclick=settings;
function history(){const historyTerms=Array.from({length:state.termCount+6},(_,i)=>i-6);modal(`<h2>Completed courses</h2><p class="muted">Search courses and record the term you completed each one, including terms before this degree.</p><label class="wishlist-search">Search completed courses<input type="search" id="history-search" placeholder="Course code or name"></label><div class="checklist">${courses.map(c=>`<div class="history-row" data-history-row="${c.id}"><label class="list-choice"><input type="checkbox" value="${c.id}" ${state.completed.includes(c.id)?'checked':''}><span><b>${c.code}</b> — ${c.name}</span></label><label class="small">Completed in<select data-completed-term="${c.id}" aria-label="Completion term for ${c.code}"><option value="">Earlier / term unknown</option>${historyTerms.map(i=>`<option value="${i}" ${Number.isInteger(state.completedTerms?.[c.id])&&state.completedTerms[c.id]===i?'selected':''}>${term(state,i).title}${i<0?' · before degree':''}</option>`).join('')}</select></label></div>`).join('')}</div><p id="history-empty" class="empty" hidden>No courses match your search.</p><p class="small muted">Transcript import · future enhancement</p><div class="dialog-actions"><button class="primary" id="save-history">Update history</button></div>`);$('#history-search').oninput=e=>{const query=e.target.value.toLowerCase().replace(/\s/g,'');let count=0;document.querySelectorAll('[data-history-row]').forEach(row=>{const c=byId[row.dataset.historyRow];row.hidden=!(c.code+c.name).toLowerCase().replace(/\s/g,'').includes(query);if(!row.hidden)count++});$('#history-empty').hidden=count>0};$('#save-history').onclick=()=>{const checked=[...$('#modal-body').querySelectorAll('input[type=checkbox]:checked')].map(e=>e.value);state.completedTerms=state.completedTerms||{};for(const id of checked){const value=$(`[data-completed-term="${id}"]`).value;if(value!==''){state.completedTerms[id]=Number(value);state.positions[id]=Number(value)}else{if(state.completedTerms[id]!=null)delete state.positions[id];delete state.completedTerms[id]}}for(const id of state.completed){if(!checked.includes(id)&&state.completedTerms[id]!=null){delete state.positions[id];delete state.completedTerms[id]}}state.completed=checked;save();close();render()}}
function browse(group=null,destination=null,query=''){const found=courses.filter(c=>(!group||c.group===group)&&(!query||(c.code+' '+c.name).toLowerCase().replace(/\s/g,'').includes(query.toLowerCase().replace(/\s/g,''))));modal(`<h2>${group?groups[group].name:'Course search'}</h2><label class="wishlist-search">Search courses<input id="picker-search" type="search" placeholder="Course code or name" value="${escape(query)}"></label><p class="small muted">${query?'Results for “'+escape(query)+'”':'Sample eligible courses'}</p>${found.map(c=>`<div class="result"><div class="row between"><h3>${c.code} · ${c.name}</h3><span class="tag">${c.offered.join(', ')}</span></div><p class="small muted">${groups[c.group].name} · ${c.credits} credits · prerequisites: ${c.prereqs.map(p=>byId[p].code).join(', ')||'None'}</p><div class="row" style="margin-top:10px"><button data-wish="${c.id}">${state.wishlist.includes(c.id)?'Remove from wishlist':'Add to wishlist'}</button><button data-place="${c.id}" class="outline">Add to plan</button><a target="_blank" rel="noopener" href="https://uwflow.com/course/${c.id.toLowerCase()}">UWFlow ↗</a></div></div>`).join('')||'<p class="empty">No sample courses found.</p>'}`);$('#picker-search').oninput=e=>{const pos=e.target.selectionStart;browse(group,destination,e.target.value);$('#picker-search').focus();$('#picker-search').setSelectionRange(pos,pos)};$('#modal-body').querySelectorAll('[data-wish]').forEach(b=>b.onclick=()=>{toggleWish(b.dataset.wish);browse(group,destination,query)});$('#modal-body').querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const id=b.dataset.place;close();if(destination!==null)move(id,destination);else chooseTerm(id)})}
function chooseTerm(id){modal(`<h2>Schedule ${byId[id].code}</h2><p class="muted">Choose a four-month term. Conflicts will be flagged.</p><select id="choose-term" style="width:100%;margin-top:20px">${Array.from({length:state.termCount},(_,i)=>`<option value="${i}">${term(state,i).title} · ${term(state,i).type}</option>`).join('')}</select><div class="dialog-actions"><button class="primary" id="place-course">Add to term</button></div>`);$('#place-course').onclick=()=>{const t=$('#choose-term').value;close();tab='planner';state.viewStart=Math.min(Number(t),Math.max(0,state.termCount-6));move(id,t)}}
function toggleWish(id){state.wishlist=state.wishlist.includes(id)?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];save();render()}
function reorder(id,index){const a=state.wishlist.indexOf(id);if(a<0)return;state.wishlist.splice(a,1);state.wishlist.splice(Math.max(0,Math.min(index,state.wishlist.length)),0,id);save();render()}
function doGenerate(){const result=generate(state);state=result.next;tab='planner';state.viewStart=0;save();render();modal(`<h2>Plan generated</h2><p>Required courses are considered first, followed by wishlist priority.</p><div class="notice">${state.wishlist.filter(id=>state.positions[id]!=null).length} / ${state.wishlist.length} wishlist courses scheduled.</div>${result.unplaced.map(id=>`<div class="notice warning">${byId[id].code}: no term meets the sample prerequisites, offerings, antirequisites and course-load constraints.</div>`).join('')}<p class="small muted">Existing placements are preserved. Review validation for existing conflicts and outstanding requirements. This prototype uses a greedy scheduling heuristic, not an optimal solver.</p><div class="dialog-actions"><button id="review-generated" class="primary">Review plan</button></div>`);$('#review-generated').onclick=close}
function bind(){if($('#toggle-sidebar'))$('#toggle-sidebar').onclick=()=>{state.hideSidebar=!state.hideSidebar;save();render()};document.querySelectorAll('[data-add-course]').forEach(b=>b.onclick=()=>browse(null,b.dataset.addCourse));document.querySelectorAll('[data-section]').forEach(d=>d.ontoggle=()=>{state.collapsed=state.collapsed||{};state.collapsed[d.dataset.section]=!d.open;save()});if($('#full-degree'))$('#full-degree').onchange=e=>{state.fullDegree=e.target.checked;save();render()};if($('#show-work'))$('#show-work').onchange=e=>{state.showWork=e.target.checked;state.viewStart=0;save();render()};if($('#wishlist-search'))$('#wishlist-search').oninput=e=>{const pos=e.target.selectionStart;wishQuery=e.target.value;render();$('#wishlist-search').focus();$('#wishlist-search').setSelectionRange(pos,pos)};const on=(s,fn)=>{if($(s))$(s).onclick=fn};on('#history',history);on('#open-planner',()=>changeTab('planner'));on('#save',()=>save(true));on('#generate',doGenerate);on('#browse',()=>browse());on('#move-selected',()=>move(state.selected,$('#move-target').value));on('#previous',()=>{state.viewStart=Math.max(0,state.viewStart-(tab==='roadmap'?3:4));render()});on('#next',()=>{state.viewStart=Math.min(Math.max(0,(visibleTerms(state,tab).length-(tab==='roadmap'?5:6))),state.viewStart+(tab==='roadmap'?3:4));render()});on('#add-term',()=>{state.termTypes[state.termCount]='Study';state.termCount++;state.viewStart=Math.max(0,state.termCount-6);save();render()});if($('#lines'))$('#lines').onchange=e=>{lines=e.target.checked;draw()};if($('#limit'))$('#limit').onchange=e=>{state.limit=Number(e.target.value);save();render()};document.querySelectorAll('[data-type]').forEach(e=>e.onchange=()=>{state.termTypes[e.dataset.type]=e.value;save();render()});document.querySelectorAll('[data-course]').forEach(b=>{b.onclick=()=>{state.selected=b.dataset.course;render()};b.ondragstart=e=>{dragId=b.dataset.course;e.dataTransfer.setData('text/plain',dragId)};b.ondragover=e=>e.preventDefault();b.ondrop=e=>{e.preventDefault();e.stopPropagation();const id=dragId||e.dataTransfer.getData('text/plain');if(!byId[id]||id===b.dataset.course)return;state.order=state.order||courses.map(c=>c.id);state.order=state.order.filter(x=>x!==id);state.order.splice(state.order.indexOf(b.dataset.course),0,id);move(id,state.positions[b.dataset.course]??'')};b.ondragend=()=>dragId=null});document.querySelectorAll('[data-term]').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('over')};el.ondragleave=()=>el.classList.remove('over');el.ondrop=e=>{e.preventDefault();el.classList.remove('over');const id=dragId||e.dataTransfer.getData('text/plain');if(byId[id])move(id,el.dataset.term)}});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>browse(b.dataset.group,b.dataset.destination));document.querySelectorAll('[data-wish]').forEach(b=>b.onclick=()=>toggleWish(b.dataset.wish));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{const id=b.dataset.plan;if(state.positions[id]!=null){state.selected=id;tab='planner';state.viewStart=Math.min(state.positions[id],state.termCount-6);render()}else chooseTerm(id)});document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>reorder(b.dataset.up,state.wishlist.indexOf(b.dataset.up)-1));document.querySelectorAll('[data-down]').forEach(b=>b.onclick=()=>reorder(b.dataset.down,state.wishlist.indexOf(b.dataset.down)+1));document.querySelectorAll('[data-priority]').forEach(el=>{el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.priority);el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();reorder(e.dataTransfer.getData('text/plain'),state.wishlist.indexOf(el.dataset.priority))}})}
$('#search').onkeydown=e=>{if(e.key==='Enter')browse(null,null,e.target.value.trim())};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}});render();

document.addEventListener('click',e=>{if(!state.selected||e.target.closest('[data-course],button,a,input,select,label,summary,dialog,.sidebar'))return;state.selected=null;save();render()});
